import gzip

from botforensics.pipeline import run
from botforensics.sample import make_sample

RAW = (
    '203.0.113.7 - - [14/Oct/2026:03:00:00 +0000] "GET /secretadm/?a=1 HTTP/1.1" 200 1 '
    '"https://site.example/secretadm/?x=y" "Mozilla/5.0 Chrome/150.0.0.0"\n'
    '203.0.113.8 - - [15/Oct/2026:03:00:00 +0000] "GET / HTTP/1.1" 200 1 "-" "-"\n'
)
CERBER = (
    '"Generated by:","WP Cerber Security 9.10"\n\n'
    '"Adresse IP","Événement","Statut","Nom d’utilisateur","Unix Timestamp","URL"\n'
    '"203.0.113.7","Connecté","","adminuser","1791954000.0","site.example/secretadm/"\n'
)


def test_sample_is_pseudonymised_and_reprocessable(tmp_path, settings):
    raw = tmp_path / "raw"
    (raw / "apache").mkdir(parents=True)
    (raw / "cerber").mkdir()
    with gzip.open(raw / "apache" / "access-2026-10-14.log.gz", "wt") as fh:
        fh.write(RAW)
    (raw / "cerber" / "wp-cerber-activity-test.csv").write_text(CERBER, encoding="utf-8")
    out = tmp_path / "sample"

    counts = make_sample(raw, "2026-10-14", out, settings)

    assert counts == {"requests": 1, "cerber_events": 1, "ips": 1}
    text = "".join(p.read_text(encoding="utf-8") for p in out.rglob("*") if p.is_file())
    for secret in ("203.0.113", "adminuser", "secretadm", "?a=1", "?x=y"):
        assert secret not in text
    result = run(out, settings)
    assert result.stats.parsed == 1
    assert result.actors["category"].iloc[0] == "internal"  # Cerber logged_in
